import InputText from 'primevue/inputtext';
import Select from 'primevue/select';

export default {
    name: "Detail",
    data() {
      return {
        size: [
          { name: 'XS', code: 'XS' },
          { name: 'S', code: 'S' },
          { name: 'M', code: 'M' },
          { name: 'L', code: 'L' },
          { name: 'XL', code: 'XL' },
          { name: 'XXL', code: 'XXL' },
        ],
        color: [
          { name: 'Red', code: 'RED', ccode: '#CD5C5C' },
          { name: 'Blue', code: 'BLUE', ccode: '#0000FF' },
          { name: 'Green', code: 'GREEN', ccode: '#008000' },
          { name: 'Black', code: 'BLACK', ccode: '#000000' },
          { name: 'White', code: 'WHITE', ccode: '#FFFFFF' },
          { name: 'Yellow', code: 'YELLOW', ccode: '#FFFF00' },
        ],
        selectedSize: { name: 'XL', code: 'XL' },
        selectedColor: { name: 'Red', code: 'RED' }
      };
    },
    components: {
      InputText,
      Select
    },
    methods: {

    },
  };
